import {
  IsDateString,
  IsInt,
  IsNotEmpty,
  IsNumber,
  IsOptional,
  IsString,
  IsUUID,
  Min,
} from 'class-validator';

/**
 * DTO for manually creating a prediction.
 * Note: In normal flow, predictions are auto-generated by the system.
 * This DTO is only used if manual creation via API is needed.
 */
export class CreatePredictionDto {
  @IsDateString()
  @IsNotEmpty()
  estimationSortieDate!: string;

  @IsInt()
  @IsNotEmpty()
  @Min(0)
  quantiteRecommande!: number;

  @IsNumber()
  @IsNotEmpty()
  @Min(0)
  CMJ!: number;

  @IsUUID()
  @IsNotEmpty()
  produitId!: string;

  @IsString()
  @IsOptional()
  explication?: string;

  @IsString()
  @IsOptional()
  tendance?: string;
}
